import sys

data = sys.stdin.read().split()
n, m = int(data[0]), int(data[1])
a = list(map(int, data[2:2 + n]))
b = list(map(int, data[2 + n:2 + n + m]))
pa = {v: i for i, v in enumerate(a)}
pb = {v: j for j, v in enumerate(b)}
f1 = [0] * (n + 1)
f2 = [0] * (m + 1)
# process by decreasing value so that cross references are ready
order = sorted([(a[i], 0, i) for i in range(n)] + [(b[j], 1, j) for j in range(m)], reverse=True)
for v, which, idx in order:
    if which == 0:
        best = f1[idx + 1]
        if v in pb:
            best = max(best, f2[pb[v] + 1])
        f1[idx] = v + best
    else:
        best = f2[idx + 1]
        if v in pa:
            best = max(best, f1[pa[v] + 1])
        f2[idx] = v + best
print(max(f1[0], f2[0]))

